import numpy as np
import scipy.signal as ss
import scipy.signal.windows as sw
import signal_design_expected as X

def close(x, ref, rtol: float = 1e-9, atol: float = 1e-12) -> bool:
    a = np.asarray(x).ravel()
    if a.shape[0] != len(ref):
        print('size', a.shape[0], len(ref))
        return False
    ok = True
    for i in range(len(ref)):
        if abs(a[i] - ref[i]) > atol + rtol * abs(ref[i]):
            print('mismatch', i, a[i], ref[i])
            ok = False
    return ok

def closeabs(x, ref, rtol: float = 1e-9, atol: float = 1e-12) -> bool:
    a = np.asarray(x).ravel()
    ok = a.shape[0] == len(ref)
    for i in range(len(ref)):
        if abs(abs(a[i]) - abs(ref[i])) > atol + rtol * abs(ref[i]):
            print('mismatch', i, a[i], ref[i])
            ok = False
    return ok

def cat4(r):
    return np.concatenate((r[0].ravel(), r[1].ravel(), r[2].ravel(), r[3].ravel()))

A = np.array([[0., 1.], [-2., -3.]])
B = np.array([[0.], [1.]])
C = np.array([[1., 0.]])
D = np.array([[0.]])

@test
def test_transforms():
    den = [1.0, 2.0, 2.0, 1.0]
    b, a = ss.lp2lp([1.0], den, 3.0)
    assert close(b, X.lp2lp_b) and close(a, X.lp2lp_a)
    b, a = ss.lp2hp([1.0], den, 3.0)
    assert close(b, X.lp2hp_b) and close(a, X.lp2hp_a)
    b, a = ss.lp2bp([1.0], den, 3.0, 0.5)
    assert close(b, X.lp2bp_b) and close(a, X.lp2bp_a)
    b, a = ss.lp2bs([1.0], den, 3.0, 0.5)
    assert close(b, X.lp2bs_b) and close(a, X.lp2bs_a)
    b, a = ss.bilinear([1.0, 0.5], den, fs=10.0)
    assert close(b, X.bil_b) and close(a, X.bil_a)
    w, h = ss.freqs([1.0], den, worN=20)
    assert close(w, X.freqs_w) and close(h, X.freqs_h)
    w, h = ss.freqs([1.0], den, worN=np.linspace(0.1, 5, 7))
    assert close(h, X.freqs_h2)
    z, p, k = ss.buttap(4)
    w, h = ss.freqs_zpk(z, p, k, worN=15)
    assert close(w, X.fzpk_w) and close(h, X.fzpk_h)
test_transforms()

@test
def test_order_design():
    n, wn = ss.cheb2ord(0.2, 0.3, 3, 40)
    assert close([float(n), wn], X.c2o)
    n, wn2 = ss.cheb2ord([0.2, 0.5], [0.1, 0.6], 3, 40)
    assert close([float(n), wn2[0], wn2[1]], X.c2o_bp, 1e-6)
    n, wn2 = ss.cheb2ord([0.1, 0.6], [0.2, 0.5], 3, 40)
    assert close([float(n), wn2[0], wn2[1]], X.c2o_bs, 1e-6)
    b, a = ss.iirdesign(0.2, 0.3, 1, 40)
    assert close(b, X.iird_b, 1e-7) and close(a, X.iird_a, 1e-7)
    b, a = ss.iirdesign([0.2, 0.5], [0.1, 0.6], 1, 40, ftype='cheby2')
    assert close(b, X.iird2_b, 1e-7, 1e-10) and close(a, X.iird2_a, 1e-7)
    sos = ss.iirdesign(0.3, 0.2, 1, 30, ftype='butter', output='sos')
    assert close(sos, X.iird3, 1e-7)
    b, a = ss.iircomb(100.0, 30.0, fs=1000.0)
    assert close(b, X.comb_b) and close(a, X.comb_a)
    b, a = ss.iircomb(100.0, 30.0, ftype='peak', fs=1000.0, pass_zero=True)
    assert close(b, X.combp_b) and close(a, X.combp_a)
test_order_design()

@test
def test_fir():
    assert close(ss.remez(31, [0, 0.1, 0.2, 0.5], [1, 0]), X.remez1, 1e-8, 1e-11)
    assert close(ss.remez(30, [0, 100, 150, 500], [1, 0], fs=1000), X.remez2, 1e-8, 1e-11)
    assert close(ss.remez(21, [0.05, 0.45], [1], type='hilbert'), X.remez3, 1e-8, 1e-11)
    assert close(ss.remez(20, [0, 0.4], [1], type='differentiator'), X.remez4, 1e-8, 1e-11)
    assert close(ss.remez(41, [0, 0.1, 0.15, 0.3, 0.35, 0.5], [0, 1, 0], weight=[1, 2, 1]), X.remez5, 1e-8, 1e-11)
    assert close(ss.firls(31, [0, 0.2, 0.3, 1], [1, 1, 0, 0]), X.firls1)
    assert close(ss.firls(25, [0, 100, 150, 300, 350, 500], [0, 0, 1, 1, 0, 0], weight=[1, 3, 1], fs=1000), X.firls2)
    h = ss.firwin(31, 0.3)
    assert close(ss.minimum_phase(h), X.minph1, 1e-8, 1e-11)
    # ill-conditioned: log(sqrt(H+ds)) near the stopband minimum depends on the
    # last bits of the FFT (numpy.fft vs scipy.fft already differ by ~1e-4)
    assert close(ss.minimum_phase(h, method='hilbert'), X.minph2, 0.0, 1e-3)
    assert close(ss.minimum_phase(h, half=False, n_fft=256), X.minph3, 1e-8, 1e-11)
test_fir()

@test
def test_lti():
    assert close(cat4(ss.tf2ss([1.0, 3.0, 3.0], [1.0, 2.0, 1.0])), X.tf2ss)
    assert close(cat4(ss.tf2ss([2.0, 1.0], [1.0, 5.0, 6.0, 2.0])), X.tf2ss2)
    num, den = ss.ss2tf(A, B, C, D)
    assert close(num, X.ss2tf_n) and close(den, X.ss2tf_d)
    z, p, k = ss.ss2zpk(A, B, C + np.array([[0., 1.]]), D)
    assert close(z, X.ss2zpk_z) and close(p, X.ss2zpk_p) and close([k], X.ss2zpk_k)
    r = ss.cont2discrete((A, B, C, D), 0.1)
    assert close(cat4(r), X.c2d_zoh)
    assert close(cat4(ss.cont2discrete((A, B, C, D), 0.1, method='bilinear')), X.c2d_bil)
    assert close(cat4(ss.cont2discrete((A, B, C, D), 0.1, method='foh')), X.c2d_foh)
    assert close(cat4(ss.cont2discrete((A, B, C, D), 0.1, method='impulse')), X.c2d_imp)
    rt = ss.cont2discrete(([1.0], [1.0, 3.0, 2.0]), 0.1)
    assert close(rt[0], X.c2d_tf_n, 1e-8, 1e-12) and close(rt[1], X.c2d_tf_d)
    t = np.linspace(0, 5, 51)
    u = np.sin(t)
    tt, y, x = ss.lsim((A, B, C, D), u, t)
    assert close(y, X.lsim_y) and close(x, X.lsim_x)
    tt, y, x = ss.lsim(([1.0], [1.0, 3.0, 2.0]), u, t, interp=False)
    assert close(y, X.lsim2_y)
    tt, y = ss.impulse((A, B, C, D), T=t)
    assert close(y, X.imp_y)
    tt, y = ss.step(([1.0], [1.0, 3.0, 2.0]), T=t)
    assert close(y, X.step_y)
    tt, y = ss.step((A, B, C, D), N=20)
    assert close(tt, X.step_t) and close(y, X.step_y2)
    w, mag, ph = ss.bode(([1.0], [1.0, 3.0, 2.0]), w=np.logspace(-1, 1, 9))
    assert close(mag, X.bode_m) and close(ph, X.bode_p)
    w, h = ss.freqresp(([1.0], [1.0, 3.0, 2.0]), w=np.logspace(-1, 1, 9))
    assert close(h, X.fresp)
    tt, y, x = ss.dlsim(([1.0], [1.0, -0.5], 0.1), np.ones(10))
    assert close(y, X.dlsim)
    tt, ys = ss.dimpulse(([1.0, 0.5], [1.0, -0.5, 0.2], 0.1), n=12)
    assert close(ys[0], X.dimp)
    tt, ys = ss.dstep(([1.0, 0.5], [1.0, -0.5, 0.2], 0.1), n=12)
    assert close(ys[0], X.dstep)
    w, h = ss.dfreqresp(([1.0, 0.5], [1.0, -0.5, 0.2], 0.1), w=np.linspace(0, np.pi, 7))
    assert close(h, X.dfresp)
    w, mag, ph = ss.dbode(([1.0, 0.5], [1.0, -0.5, 0.2], 0.1), w=np.linspace(0.1, np.pi, 7))
    assert close(w, X.dbode_w) and close(mag, X.dbode_m) and close(ph, X.dbode_p)
    sys = ss.lti(A, B, C, D)
    tt, y = sys.step(T=t)
    tt2, y2 = ss.step((A, B, C, D), T=t)
    assert close(y, [v for v in y2])
test_lti()

@test
def test_windows():
    assert close(sw.get_window('parzen', 16, fftbins=False), X.win_parzen)
    assert close(sw.get_window('parzen', 15), X.winp_parzen)
    assert close(sw.get_window('bohman', 16, fftbins=False), X.win_bohman)
    assert close(sw.get_window('bohman', 15), X.winp_bohman)
    assert close(sw.get_window('barthann', 16, fftbins=False), X.win_barthann)
    assert close(sw.get_window('barthann', 15), X.winp_barthann)
    assert close(sw.get_window('lanczos', 16, fftbins=False), X.win_lanczos)
    assert close(sw.get_window('lanczos', 15), X.winp_lanczos)
    assert close(sw.get_window(('chebwin', 60), 16, fftbins=False), X.win_cheb)
    assert close(sw.get_window(('chebwin', 60), 15), X.winp_cheb)
    assert close(sw.get_window(('general_gaussian', 1.5, 3.0), 16, fftbins=False), X.win_ggs)
    assert close(sw.get_window(('general_gaussian', 1.5, 3.0), 15), X.winp_ggs)
    assert close(sw.get_window(('kbd', 4.0), 16, fftbins=False), X.win_kbd)
    assert close(sw.get_window('taylor', 16, fftbins=False), X.win_taylor)
    assert close(sw.get_window('taylor', 15), X.winp_taylor)
    assert close(sw.get_window(('taylor', 5, 35), 16, fftbins=False), X.win_taylor2)
    assert close(sw.get_window(('taylor', 5, 35), 15), X.winp_taylor2)
    assert close(sw.get_window(('dpss', 2.5), 16, fftbins=False), X.win_dpss, 1e-8, 1e-11)
    assert close(sw.get_window(('dpss', 2.5), 15), X.winp_dpss, 1e-8, 1e-11)
    assert close(sw.chebwin(15, 50), X.cheb_odd)
    assert close(sw.dpss(64, 3.5, Kmax=4), X.dpss_k, 1e-8, 1e-11)
    w, r = sw.dpss(51, 2.0, Kmax=3, return_ratios=True)
    assert close(w, X.dpss_k2, 1e-8, 1e-11) and close(r, X.dpss_r, 1e-9)
    assert close(sw.dpss(32, 2.0, norm='subsample'), X.dpss_sub, 1e-8, 1e-11)
test_windows()
